SELECT count(*) FROM public.chartevents chartevents
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT a.hadm_id AS key1 FROM public.admissions a, public.drgcodes g, public.services s WHERE g.hadm_id = a.hadm_id AND g.drg_type = 'APR' AND g.drg_severity >= 3 AND s.hadm_id = a.hadm_id AND s.curr_service = 'MED') x) b1 ON chartevents.hadm_id = b1.key1
  LEFT JOIN (SELECT DISTINCT d.charttime AS key1, d.stay_id AS key2, 1 AS hit FROM (SELECT DISTINCT charttime, stay_id FROM public.chartevents) d, public.procedureevents pe, public.d_items di WHERE di.itemid = pe.itemid AND di.label = 'Invasive Ventilation' AND d.charttime >= pe.starttime AND d.charttime <= pe.endtime AND d.stay_id = pe.stay_id) b2 ON chartevents.charttime = b2.key1 AND chartevents.stay_id = b2.key2
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT a.hadm_id AS key1 FROM public.admissions a, public.diagnoses_icd d, public.d_icd_diagnoses dd WHERE d.hadm_id = a.hadm_id AND (d.icd_code = 'F329' OR d.icd_code = '311') AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version) x) b3 ON chartevents.hadm_id = b3.key1
WHERE ((b1.hit IS NOT NULL OR b2.hit IS NOT NULL) AND b3.hit IS NULL);
